import java.util.Arrays;

class Solution {
    public boolean isFascinating(int n) {
        String s = "" + n + (2 * n) + (3 * n);
        char[] chars = s.toCharArray();
        Arrays.sort(chars);
        return new String(chars).equals("123456789");
    }
}

var isFascinating = function(n) {
    const s = "" + n + (2 * n) + (3 * n);
    return s.split("").sort().join("") === "123456789";
};
